// @FIGURE_CODE_BEGIN
// axis triad → black Line segments with ConeGeometry arrowheads and italic x,y,z labels
// s orbital → translucent blue SphereGeometry centered at an atomic-origin panel
// px orbital → two tapered teardrop Mesh lobes aligned on chemistry x, red negative phase and blue positive phase
// py orbital → two tapered teardrop Mesh lobes aligned on chemistry y, red negative phase and blue positive phase
// pz orbital → two tapered teardrop Mesh lobes aligned on chemistry z, red negative phase and blue positive phase
// orbital names → HTML labels s, p_x, p_y, p_z beneath atomic panels
// hybridization arrow → grey Line shaft plus ConeGeometry arrowhead with Hybridization label
// individual sp3 hybrids → four orange/yellow large teardrop lobes with small opposite back-lobes in a 2×2 grid
// tetrahedral axes → black axis triad at shared hybrid origin
// tetrahedral hybrids → four shared-origin orange/yellow sp3 lobe pairs directed to tetrahedral corners
// central atom marker → small black SphereGeometry at tetrahedral origin
// direction guides → faint grey Lines through hybrid directions and back-lobes
// 109.5 annotation → grey curved Line arc and label between two tetrahedral lobes
// downward arrow → grey vertical Line arrow and Gives a tetrahedral arrangement label

scene.background = new THREE.Color(0xffffff);
renderer.setClearColor(0xffffff, 1);

const ambient = new THREE.AmbientLight(0xffffff, 0.72);
const key = new THREE.DirectionalLight(0xffffff, 0.82);
key.position.set(3, 5, 4);
const fill = new THREE.DirectionalLight(0xffffff, 0.38);
fill.position.set(-4, 2, -3);
scene.add(ambient, key, fill);

const AX = new THREE.Vector3(1, 0, 0);
const AY = new THREE.Vector3(0, 0, 1);  // chemistry y: receding
const AZ = new THREE.Vector3(0, 1, 0);  // chemistry z: vertical in the diagram

const blue = 0x4f83c4;
const red = 0xef6b73;
const orange = 0xf6a21a;
const yellow = 0xffd36b;
const grey = 0x8a8a8a;
const black = 0x000000;

const stages = {
  atomic: new THREE.Group(),
  individual: new THREE.Group(),
  tetra: new THREE.Group()
};
scene.add(stages.atomic, stages.individual, stages.tetra);

const labelSpecs = [];
const labelEntries = [];
function qLabel(stage, html, pos, opts = {}) {
  labelSpecs.push({ stage, html, pos: pos.clone(), opts });
}

function matOrb(color, opacity = 0.78) {
  return new THREE.MeshPhongMaterial({
    color,
    emissive: color,
    emissiveIntensity: 0.08,
    shininess: 72,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}
const matBlue = matOrb(blue, 0.68);
const matRed = matOrb(red, 0.68);
const matS = matOrb(blue, 0.48);
const matOrangeBase = matOrb(orange, 0.82);
const matYellow = matOrb(yellow, 0.34);
const matBlack = new THREE.MeshBasicMaterial({ color: black });
const matGuide = new THREE.LineBasicMaterial({ color: grey, transparent: true, opacity: 0.62 });
const matAxis = new THREE.LineBasicMaterial({ color: black });
const matArrow = new THREE.LineBasicMaterial({ color: grey });

function makeTeardropGeometry(rings = 30, segs = 36) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= rings; i++) {
    const t = i / rings;
    const x = t;
    const profile = Math.pow(Math.sin(Math.PI * t), 0.72) * (0.38 + 0.88 * t);
    const r = profile;
    for (let j = 0; j < segs; j++) {
      const a = 2 * Math.PI * j / segs;
      verts.push(x, r * Math.cos(a), r * Math.sin(a));
    }
  }
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      const a = i * segs + j;
      const b = i * segs + ((j + 1) % segs);
      const c = (i + 1) * segs + j;
      const d0 = (i + 1) * segs + ((j + 1) % segs);
      indices.push(a, c, b, b, c, d0);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  return g;
}
const lobeGeom = makeTeardropGeometry();

function setAlong(obj, dir) {
  obj.quaternion.setFromUnitVectors(AX, dir.clone().normalize());
}
function makeLobe(origin, dir, length, radius, material) {
  const m = new THREE.Mesh(lobeGeom, material);
  m.position.copy(origin);
  setAlong(m, dir);
  m.scale.set(length, radius, radius);
  return m;
}
function addLine(group, pts, material = matAxis) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(g, material);
  group.add(line);
  return line;
}
function addConeArrow(group, end, dir, color = black, h = 0.16, r = 0.055) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 24), new THREE.MeshBasicMaterial({ color }));
  cone.position.copy(end).addScaledVector(dir.clone().normalize(), -h / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  group.add(cone);
  return cone;
}
function addAxisTriad(group, center, stage, len = 1.15) {
  const axes = [
    { v: AX, lab: '<i>x</i>', neg: 0.76, pos: len, off: [9, 2] },
    { v: AY, lab: '<i>y</i>', neg: 0.58, pos: len * 0.92, off: [8, -4] },
    { v: AZ, lab: '<i>z</i>', neg: 0.72, pos: len, off: [0, -10] }
  ];
  for (const a of axes) {
    addLine(group, [
      center.clone().addScaledVector(a.v, -a.neg),
      center.clone().addScaledVector(a.v, a.pos - 0.12)
    ], matAxis);
    addConeArrow(group, center.clone().addScaledVector(a.v, a.pos), a.v, black, 0.15, 0.045);
    qLabel(stage, a.lab, center.clone().addScaledVector(a.v, a.pos + 0.16), {
      fontSize: '22px',
      offset: a.off,
      contrib: null
    });
  }
}

const contribGroups = { showS: [], showPx: [], showPy: [], showPz: [] };
const atomicCenters = {
  showS: new THREE.Vector3(-1.42, 0.88, 0),
  showPx: new THREE.Vector3(1.42, 0.88, 0),
  showPy: new THREE.Vector3(-1.42, -0.88, 0),
  showPz: new THREE.Vector3(1.42, -0.88, 0)
};

function buildAtomic() {
  for (const k of Object.keys(atomicCenters)) addAxisTriad(stages.atomic, atomicCenters[k], 'atomic', 1.12);

  const sG = new THREE.Group();
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.42, 48, 32), matS);
  s.position.copy(atomicCenters.showS);
  sG.add(s);
  stages.atomic.add(sG);
  contribGroups.showS.push(sG);
  qLabel('atomic', '<i>s</i>', atomicCenters.showS.clone().add(new THREE.Vector3(0, -0.88, 0)), {
    fontSize: '24px',
    contrib: 'showS'
  });

  const pxG = new THREE.Group();
  pxG.add(makeLobe(atomicCenters.showPx, AX, 0.95, 0.34, matBlue));
  pxG.add(makeLobe(atomicCenters.showPx, AX.clone().negate(), 0.95, 0.34, matRed));
  stages.atomic.add(pxG);
  contribGroups.showPx.push(pxG);
  qLabel('atomic', '<i>p</i><sub>x</sub>', atomicCenters.showPx.clone().add(new THREE.Vector3(0, -0.88, 0)), {
    fontSize: '24px',
    contrib: 'showPx'
  });

  const pyG = new THREE.Group();
  pyG.add(makeLobe(atomicCenters.showPy, AY, 0.95, 0.34, matBlue));
  pyG.add(makeLobe(atomicCenters.showPy, AY.clone().negate(), 0.95, 0.34, matRed));
  stages.atomic.add(pyG);
  contribGroups.showPy.push(pyG);
  qLabel('atomic', '<i>p</i><sub>y</sub>', atomicCenters.showPy.clone().add(new THREE.Vector3(0, -0.88, 0)), {
    fontSize: '24px',
    contrib: 'showPy'
  });

  const pzG = new THREE.Group();
  pzG.add(makeLobe(atomicCenters.showPz, AZ, 0.95, 0.34, matBlue));
  pzG.add(makeLobe(atomicCenters.showPz, AZ.clone().negate(), 0.95, 0.34, matRed));
  stages.atomic.add(pzG);
  contribGroups.showPz.push(pzG);
  qLabel('atomic', '<i>p</i><sub>z</sub>', atomicCenters.showPz.clone().add(new THREE.Vector3(0, -0.88, 0)), {
    fontSize: '24px',
    contrib: 'showPz'
  });

  registerInteractive(s, {
    title: 's orbital',
    tooltip: 'Spherical s orbital',
    body: 'The s orbital contributes equally to every sp3 hybrid, helping make the four hybrids equivalent.'
  });
  registerInteractive(pxG.children[0], {
    title: 'pₓ orbital',
    tooltip: 'pₓ phase lobes',
    body: 'The pₓ orbital has opposite phases on the +x and −x sides. Hybridization combines these phases with s, pᵧ, and p_z.'
  });
}
buildAtomic();

const canonical = [
  new THREE.Vector3(1, 1, 1),
  new THREE.Vector3(1, -1, -1),
  new THREE.Vector3(-1, -1, 1),
  new THREE.Vector3(-1, 1, -1)
];
const targetTop = new THREE.Vector3(0, 1, 0);
const targetRight = new THREE.Vector3(Math.sqrt(8 / 9), -1 / 3, 0).normalize();
const c1 = canonical[0].clone().normalize();
const c2 = canonical[1].clone().normalize();
const q1 = new THREE.Quaternion().setFromUnitVectors(c1, targetTop);
const c2p = c2.clone().applyQuaternion(q1);
const aPerp = c2p.clone().addScaledVector(targetTop, -c2p.dot(targetTop)).normalize();
const bPerp = targetRight.clone().addScaledVector(targetTop, -targetRight.dot(targetTop)).normalize();
const signed = Math.atan2(targetTop.dot(aPerp.clone().cross(bPerp)), aPerp.dot(bPerp));
const q2 = new THREE.Quaternion().setFromAxisAngle(targetTop, signed);
const hybridRot = q2.clone().multiply(q1);
function rotHybrid(v) { return v.clone().normalize().applyQuaternion(hybridRot).normalize(); }

const individualCenters = [
  new THREE.Vector3(-1.42, 0.88, 0),
  new THREE.Vector3(1.42, 0.88, 0),
  new THREE.Vector3(-1.42, -0.88, 0),
  new THREE.Vector3(1.42, -0.88, 0)
];
const hybridItems = [];

function makeHybridPair(group, origin, baseLen, baseRad, stage, index) {
  const matF = matOrangeBase.clone();
  const matB = matOrangeBase.clone();
  const f = makeLobe(origin, AZ, baseLen, baseRad, matF);
  const b = makeLobe(origin, AZ.clone().negate(), baseLen * 0.24, baseRad * 0.26, matB);
  const h = makeLobe(origin, AZ, baseLen * 0.68, baseRad * 0.46, matYellow.clone());
  const smallSphere = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 16), matOrangeBase.clone());
  smallSphere.position.copy(origin);
  smallSphere.visible = false;
  group.add(f, b, h, smallSphere);
  hybridItems.push({ origin, baseLen, baseRad, f, b, h, smallSphere, signs: canonical[index].clone(), stage });
  registerInteractive(f, {
    title: 'sp3 hybrid orbital',
    tooltip: 'Large sp3 hybrid lobe',
    body: 'An sp3 hybrid is formed from one s and three p ingredients. With all ingredients on, every orange hybrid has the same size and shape.'
  });
}

function buildIndividual() {
  const start = new THREE.Vector3(-0.76, 1.67, 0);
  const end = new THREE.Vector3(0.76, 1.67, 0);
  addLine(stages.individual, [start, end.clone().addScaledVector(AX, -0.14)], matArrow);
  addConeArrow(stages.individual, end, AX, grey, 0.22, 0.08);
  qLabel('individual', 'Hybridization', new THREE.Vector3(0, 1.88, 0), {
    color: '#111',
    fontSize: '24px',
    offset: [0, -6]
  });
  for (let i = 0; i < 4; i++) {
    addAxisTriad(stages.individual, individualCenters[i], 'individual', 1.05);
    makeHybridPair(stages.individual, individualCenters[i], 1.05, 0.38, 'individual', i);
  }
}
buildIndividual();

let angleLabelIndex = -1;
function buildTetra() {
  const origin = new THREE.Vector3(0, -0.1, 0);
  const arrowTop = new THREE.Vector3(-0.95, 1.95, 0);
  const arrowBottom = new THREE.Vector3(-0.95, 1.25, 0);
  addLine(stages.tetra, [arrowTop, arrowBottom.clone().add(new THREE.Vector3(0, 0.12, 0))], matArrow);
  addConeArrow(stages.tetra, arrowBottom, new THREE.Vector3(0, -1, 0), grey, 0.24, 0.09);
  qLabel('tetra', 'Gives a tetrahedral<br>arrangement', new THREE.Vector3(-0.25, 1.68, 0), {
    color: '#111',
    fontSize: '24px',
    offset: [18, 0],
    background: 'rgba(255,255,255,0.72)'
  });

  addAxisTriad(stages.tetra, origin, 'tetra', 1.2);

  for (let i = 0; i < 4; i++) {
    const dir = rotHybrid(canonical[i]);
    addLine(stages.tetra, [
      origin.clone().addScaledVector(dir, -0.45),
      origin.clone().addScaledVector(dir, 1.33)
    ], matGuide);
    makeHybridPair(stages.tetra, origin, 1.15, 0.39, 'tetra', i);
  }
  const atom = new THREE.Mesh(new THREE.SphereGeometry(0.055, 24, 16), matBlack);
  atom.position.copy(origin);
  stages.tetra.add(atom);
  registerInteractive(atom, {
    title: 'Central atom',
    tooltip: 'Shared origin',
    body: 'In the tetrahedral arrangement all four sp3 hybrids share this central atom and point toward different corners of a tetrahedron.'
  });

  const d1 = rotHybrid(canonical[0]);
  const d2 = rotHybrid(canonical[1]);
  const pts = [];
  for (let i = 0; i <= 32; i++) {
    const t = i / 32;
    const v = d1.clone().lerp(d2, t).normalize();
    pts.push(origin.clone().addScaledVector(v, 0.54));
  }
  addLine(stages.tetra, pts, new THREE.LineBasicMaterial({ color: grey, transparent: true, opacity: 0.78 }));
  const mid = d1.clone().lerp(d2, 0.5).normalize();
  angleLabelIndex = labelSpecs.length;
  qLabel('tetra', '109.5°', origin.clone().addScaledVector(mid, 0.68), {
    color: '#666',
    fontSize: '16px',
    background: 'rgba(255,255,255,0.65)',
    angle: true
  });
}
buildTetra();

stages.atomic.visible = true;
stages.individual.visible = false;
stages.tetra.visible = false;

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.72
});

for (const spec of labelSpecs) {
  const e = addLabel(spec.html, spec.pos, spec.opts);
  e.stage = spec.stage;
  e.contrib = spec.opts.contrib || null;
  e.angle = !!spec.opts.angle;
  labelEntries.push(e);
}

function currentState() {
  return {
    stage: document.getElementById('viewStage').value,
    showS: document.getElementById('showS').checked,
    showPx: document.getElementById('showPx').checked,
    showPy: document.getElementById('showPy').checked,
    showPz: document.getElementById('showPz').checked
  };
}
function keyForStage(value) {
  if (value === 'Individual sp3 hybrids') return 'individual';
  if (value === 'Tetrahedral arrangement') return 'tetra';
  return 'atomic';
}
function setLobeTransform(mesh, origin, dir, len, rad) {
  mesh.visible = len > 0.015 && rad > 0.006;
  mesh.position.copy(origin);
  setAlong(mesh, dir);
  mesh.scale.set(Math.max(len, 0.001), Math.max(rad, 0.001), Math.max(rad, 0.001));
}
function updateHybrids() {
  const sOn = document.getElementById('showS').checked ? 1 : 0;
