function setLobeTransform(mesh, origin, dir, len, rad) {
  mesh.visible = len > 0.015 && rad > 0.006;
  mesh.position.copy(origin);
  setAlong(mesh, dir);
  mesh.scale.set(Math.max(len, 0.001), Math.max(rad, 0.001), Math.max(rad, 0.001));
}
function updateHybrids() {
  const sOn = document.getElementById('showS').checked ? 1 : 0;
  const pxOn = document.getElementById('showPx').checked ? 1 : 0;
  const pyOn = document.getElementById('showPy').checked ? 1 : 0;
  const pzOn = document.getElementById('showPz').checked ? 1 : 0;
  const denom = 1 + Math.sqrt(3);
  const activeCount = sOn + pxOn + pyOn + pzOn;
  for (const item of hybridItems) {
    const sx = item.signs.x * pxOn;
    const syVertical = item.signs.y * pzOn;
    const szRecede = item.signs.z * pyOn;
    const p = new THREE.Vector3(sx, syVertical, szRecede);
    const pMag = p.length();
    const op = activeCount ? 0.22 + 0.15 * activeCount : 0.04;
    item.f.material.opacity = Math.min(0.88, op + 0.22);
    item.b.material.opacity = Math.min(0.68, op);
    item.h.material.opacity = activeCount >= 3 ? 0.34 : 0.16;
    if (pMag < 1e-5) {
      item.f.visible = false;
      item.b.visible = false;
      item.h.visible = false;
      item.smallSphere.visible = !!sOn;
      item.smallSphere.scale.setScalar(sOn ? 1 : 0.001);
      continue;
    }
    item.smallSphere.visible = false;
    const dir = rotHybrid(p);
    const fAmp = Math.abs(sOn + pMag);
    const bAmp = Math.abs(sOn - pMag);
    const fScale = Math.max(0, fAmp / denom);
    const bScale = Math.max(0, bAmp / denom) * 0.92;
    setLobeTransform(item.f, item.origin, dir, item.baseLen * fScale, item.baseRad * fScale);
    setLobeTransform(item.b, item.origin, dir.clone().negate(), item.baseLen * bScale, item.baseRad * bScale);
    setLobeTransform(item.h, item.origin, dir, item.baseLen * fScale * 0.62, item.baseRad * fScale * 0.38);
  }
}
