<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// axis triads → black Line segments with ConeGeometry arrowheads; x horizontal right, z vertical, y oblique up-right
// s orbital → translucent blue SphereGeometry in the upper-left atomic panel
// p_x orbital → two teardrop Mesh lobes on x axis; blue +x lobe and red −x lobe
// p_y orbital → two teardrop Mesh lobes on y axis; blue +y up-right lobe and red −y down-left lobe
// p_z orbital → two teardrop Mesh lobes on z axis; blue +z lobe and red −z lobe
// orbital names → HTML labels s, p_x, p_y, p_z beneath atomic panels
// hybridization arrow → thick grey Cylinder shaft with ConeGeometry arrowhead and Hybridization label
// individual sp3 hybrids → four orange/yellow teardrop lobe pairs in a two-by-two layout matching the source
// downward arrow → thick grey Cylinder shaft with ConeGeometry arrowhead and Gives a tetrahedral arrangement label
// tetrahedral axes → black source-oriented axis triad at the shared hybrid origin
// tetrahedral hybrids → four shared-origin orange/yellow sp3 lobe pairs directed upward, rightward, down-left, and downward
// central atom marker → small black SphereGeometry at tetrahedral origin
// direction guides → faint grey Line segments through individual and tetrahedral hybrid lobes

scene.background = new THREE.Color(0xffffff);
renderer.setClearColor(0xffffff, 1);

const ambient = new THREE.AmbientLight(0xffffff, 0.76);
const key = new THREE.DirectionalLight(0xffffff, 0.86);
key.position.set(2.5, 5, 4);
const fill = new THREE.DirectionalLight(0xffffff, 0.38);
fill.position.set(-4, 2, -3);
scene.add(ambient, key, fill);

// Chemistry axes mapped for the printed oblique figure:
// x is screen-horizontal, z is screen-vertical, and +y is drawn diagonally up-right.
const AX = new THREE.Vector3(1, 0, 0);
const AZ = new THREE.Vector3(0, 1, 0);
const AY = new THREE.Vector3(0, 0, -1);

const blue = 0x4f83c4;
const red = 0xef6b73;
const orange = 0xf6a21a;
const yellow = 0xffd36b;
const grey = 0x8a8a8a;
const black = 0x000000;

const stages = {
  atomic: new THREE.Group(),
  individual: new THREE.Group(),
  tetra: new THREE.Group()
};
scene.add(stages.atomic, stages.individual, stages.tetra);

const labelSpecs = [];
const labelEntries = [];
function qLabel(stage, html, pos, opts = {}) {
  labelSpecs.push({ stage, html, pos: pos.clone(), opts });
}

function matOrb(color, opacity = 0.78) {
  return new THREE.MeshPhongMaterial({
    color,
    emissive: color,
    emissiveIntensity: 0.075,
    shininess: 76,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}
const matBlue = matOrb(blue, 0.66);
const matRed = matOrb(red, 0.66);
const matS = matOrb(blue, 0.46);
const matOrange = matOrb(orange, 0.84);
const matYellow = matOrb(yellow, 0.36);
const matBlack = new THREE.MeshBasicMaterial({ color: black });
const matAxis = new THREE.LineBasicMaterial({ color: black });
const matGuide = new THREE.LineBasicMaterial({ color: grey, transparent: true, opacity: 0.55 });

function makeTeardropGeometry(rings = 34, segs = 40) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= rings; i++) {
    const t = i / rings;
    const x = t;
    const r = Math.pow(Math.sin(Math.PI * t), 0.7) * (0.36 + 0.86 * t);
    for (let j = 0; j < segs; j++) {
      const a = 2 * Math.PI * j / segs;
      verts.push(x, r * Math.cos(a), r * Math.sin(a));
    }
  }
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      const a = i * segs + j;
      const b = i * segs + ((j + 1) % segs);
      const c = (i + 1) * segs + j;
      const d0 = (i + 1) * segs + ((j + 1) % segs);
      indices.push(a, c, b, b, c, d0);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  return g;
}
const lobeGeom = makeTeardropGeometry();

function setAlong(obj, dir) {
  obj.quaternion.setFromUnitVectors(AX, dir.clone().normalize());
}
function makeLobe(origin, dir, length, radius, material) {
  const m = new THREE.Mesh(lobeGeom, material);
  m.position.copy(origin);
  setAlong(m, dir);
  m.scale.set(length, radius, radius);
  return m;
}
function addLine(group, pts, material = matAxis) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(g, material);
  group.add(line);
  return line;
}
function addConeArrow(group, end, dir, color = black, h = 0.12, r = 0.04) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 24), new THREE.MeshBasicMaterial({ color }));
  const unit = dir.clone().normalize();
  cone.position.copy(end).addScaledVector(unit, -h / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(cone);
  return cone;
}
function addThickArrow(group, start, end, color = grey, radius = 0.026, headH = 0.18, headR = 0.075) {
  const dir = end.clone().sub(start);
  const len = dir.length();
  const unit = dir.clone().normalize();
  const shaftLen = Math.max(0.01, len - headH * 0.8);
  const shaftCenter = start.clone().addScaledVector(unit, shaftLen / 2);
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, shaftLen, 18),
    new THREE.MeshBasicMaterial({ color })
  );
  shaft.position.copy(shaftCenter);
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(shaft);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(headR, headH, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(end).addScaledVector(unit, -headH / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), unit);
  group.add(cone);
}
function addAxisTriad(group, center, stage, len = 0.64) {
  const axes = [
    { v: AX, lab: '<i>x</i>', neg: 0.62, pos: len, off: [10, 2] },
    { v: AY, lab: '<i>y</i>', neg: 0.52, pos: len * 0.92, off: [8, -4] },
    { v: AZ, lab: '<i>z</i>', neg: 0.58, pos: len, off: [1, -10] }
  ];
  for (const a of axes) {
    addLine(group, [
      center.clone().addScaledVector(a.v, -a.neg),
      center.clone().addScaledVector(a.v, a.pos - 0.08)
    ], matAxis);
    addConeArrow(group, center.clone().addScaledVector(a.v, a.pos), a.v, black, 0.12, 0.038);
    qLabel(stage, a.lab, center.clone().addScaledVector(a.v, a.pos + 0.11), {
      fontSize: '20px',
      offset: a.off
    });
  }
}

const contribGroups = { showS: [], showPx: [], showPy: [], showPz: [] };
const atomicCenters = {
  showS: new THREE.Vector3(-2.95, 1.12, 0),
  showPx: new THREE.Vector3(-1.62, 1.12, 0),
  showPy: new THREE.Vector3(-2.95, -0.02, 0),
  showPz: new THREE.Vector3(-1.62, -0.02, 0)
};

function buildAtomic() {
  for (const k of Object.keys(atomicCenters)) addAxisTriad(stages.atomic, atomicCenters[k], 'atomic', 0.66);

  const sG = new THREE.Group();
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.24, 48, 32), matS);
  s.position.copy(atomicCenters.showS);
  sG.add(s);
  stages.atomic.add(sG);
  contribGroups.showS.push(sG);
  qLabel('atomic', '<i>s</i>', atomicCenters.showS.clone().add(new THREE.Vector3(0, -0.56, 0)), {
    fontSize: '22px',
    contrib: 'showS'
  });

  const pxG = new THREE.Group();
  const pxBlue = makeLobe(atomicCenters.showPx, AX, 0.48, 0.19, matBlue);
  const pxRed = makeLobe(atomicCenters.showPx, AX.clone().negate(), 0.48, 0.19, matRed);
  pxG.add(pxBlue, pxRed);
  stages.atomic.add(pxG);
  contribGroups.showPx.push(pxG);
  qLabel('atomic', '<i>p</i><sub>x</sub>', atomicCenters.showPx.clone().add(new THREE.Vector3(0, -0.56, 0)), {
    fontSize: '22px',
    contrib: 'showPx'
  });

  const pyG = new THREE.Group();
  const pyBlue = makeLobe(atomicCenters.showPy, AY, 0.48, 0.19, matBlue);
  const pyRed = makeLobe(atomicCenters.showPy, AY.clone().negate(), 0.48, 0.19, matRed);
  pyG.add(pyBlue, pyRed);
  stages.atomic.add(pyG);
  contribGroups.showPy.push(pyG);
  qLabel('atomic', '<i>p</i><sub>y</sub>', atomicCenters.showPy.clone().add(new THREE.Vector3(0, -0.56, 0)), {
    fontSize: '22px',
    contrib: 'showPy'
  });

  const pzG = new THREE.Group();
  const pzBlue = makeLobe(atomicCenters.showPz, AZ, 0.48, 0.19, matBlue);
  const pzRed = makeLobe(atomicCenters.showPz, AZ.clone().negate(), 0.48, 0.19, matRed);
  pzG.add(pzBlue, pzRed);
  stages.atomic.add(pzG);
  contribGroups.showPz.push(pzG);
  qLabel('atomic', '<i>p</i><sub>z</sub>', atomicCenters.showPz.clone().add(new THREE.Vector3(0, -0.56, 0)), {
    fontSize: '22px',
    contrib: 'showPz'
  });

  registerInteractive(s, {
    title: 's orbital',
    tooltip: 'Spherical s orbital',
    body: 'The spherical s orbital mixes with three p orbitals to make four equivalent sp3 hybrids.'
  });
  registerInteractive(pxBlue, {
    title: 'pₓ orbital phase',
    tooltip: 'Blue +x lobe',
    body: 'The pₓ orbital has opposite phases on the +x and −x sides; here +x is blue and −x is red.'
  });
  registerInteractive(pyBlue, {
    title: 'pᵧ orbital phase',
    tooltip: 'Blue +y lobe',
    body: 'The +y lobe is the blue lobe drawn diagonally up-right, matching the source figure.'
  });
  registerInteractive(pzBlue, {
    title: 'p_z orbital phase',
    tooltip: 'Blue +z lobe',
    body: 'The p_z orbital is aligned vertically: blue above the origin and red below it.'
  });
}
buildAtomic();

const hybridItems = [];
function makeHybridPair(group, origin, dir, length, radius, stage, weights = {}) {
  const unit = dir.clone().normalize();
  addLine(group, [
    origin.clone().addScaledVector(unit, -0.34),
    origin.clone().addScaledVector(unit, length + 0.10)
  ], matGuide);

  const f = makeLobe(origin, unit, length, radius, matOrange.clone());
  const b = makeLobe(origin, unit.clone().negate(), length * 0.22, radius * 0.28, matOrange.clone());
  const h = makeLobe(origin, unit, length * 0.68, radius * 0.45, matYellow.clone());
  group.add(f, b, h);
  hybridItems.push({
    origin: origin.clone(),
    dir: unit,
    f,
    b,
    h,
    length,
    radius,
    weights: { s: 1, px: 1, py: 1, pz: 1, ...weights },
    stage
  });
  registerInteractive(f, {
    title: 'sp3 hybrid orbital',
    tooltip: 'Large sp3 hybrid lobe',
    body: 'Each orange lobe represents an sp3 hybrid orbital. The small lobe on the opposite side indicates the minor opposite phase.'
  });
}
function buildIndividual() {
  addThickArrow(stages.individual, new THREE.Vector3(-0.75, 1.12, 0), new THREE.Vector3(0.08, 1.12, 0), grey, 0.022, 0.17, 0.075);
  qLabel('individual', 'Hybridization', new THREE.Vector3(-0.36, 1.35, 0), {
    fontSize: '23px',
    offset: [0, -5],
    background: 'rgba(255,255,255,0.7)'
  });

  const centers = [
    new THREE.Vector3(0.86, 1.12, 0),
    new THREE.Vector3(2.10, 1.12, 0),
    new THREE.Vector3(0.86, -0.02, 0),
    new THREE.Vector3(2.10, -0.02, 0)
  ];
  const dirs = [
    AZ,
    AX,
    AY.clone().negate().addScaledVector(AX, -0.18).normalize(),
    AZ.clone().negate()
  ];
  const weights = [
    { pz: 1, px: 0.35, py: 0.35 },
    { px: 1, py: 0.35, pz: 0.35 },
    { py: 1, px: 0.45, pz: 0.35 },
    { pz: 1, px: 0.35, py: 0.35 }
  ];

  for (let i = 0; i < centers.length; i++) {
    addAxisTriad(stages.individual, centers[i], 'individual', 0.64);
    makeHybridPair(stages.individual, centers[i], dirs[i], 0.50, 0.20, 'individual', weights[i]);
  }
}
buildIndividual();

function buildTetra() {
  addThickArrow(stages.tetra, new THREE.Vector3(1.62, -0.92, 0), new THREE.Vector3(1.62, -1.46, 0), grey, 0.026, 0.18, 0.08);
  qLabel('tetra', 'Gives a tetrahedral<br>arrangement', new THREE.Vector3(1.78, -1.08, 0), {
    fontSize: '23px',
    offset: [72, 0],
    background: 'rgba(255,255,255,0.72)'
  });

  const origin = new THREE.Vector3(1.95, -2.05, 0);
  addAxisTriad(stages.tetra, origin, 'tetra', 0.62);

  const tetraDirs = [
    AZ,
    AX,
    AY.clone().negate().addScaledVector(AX, -0.42).normalize(),
    AZ.clone().negate()
  ];
  const tetraWeights = [
    { pz: 1, px: 0.55, py: 0.55 },
    { px: 1, py: 0.55, pz: 0.55 },
    { py: 1, px: 0.55, pz: 0.55 },
    { pz: 1, px: 0.55, py: 0.55 }
  ];
  for (let i = 0; i < tetraDirs.length; i++) {
    makeHybridPair(stages.tetra, origin, tetraDirs[i], 0.54, 0.205, 'tetra', tetraWeights[i]);
  }

  const atom = new THREE.Mesh(new THREE.SphereGeometry(0.035, 24, 16), matBlack);
  atom.position.copy(origin);
  stages.tetra.add(atom);
  registerInteractive(atom, {
    title: 'Central atom',
    tooltip: 'Shared hybrid origin',
    body: 'In the final panel all four sp3 hybrids share the same central atom and point in a tetrahedral arrangement.'
  });
}
buildTetra();

setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: 0.58,
  target: [-0.22, -0.42, 0],
  heightFraction: 0.84,
  distanceScale: 1.0
});

for (const spec of labelSpecs) {
  const e = addLabel(spec.html, spec.pos, spec.opts);
  e.stage = spec.stage;
  e.contrib = spec.opts.contrib || null;
  labelEntries.push(e);
}

function keyForStage(value) {
  if (value === 'Atomic orbitals') return 'atomic';
  if (value === 'Individual sp3 hybrids') return 'individual';
  if (value === 'Tetrahedral arrangement') return 'tetra';
  return 'complete';
}
function setLobeTransform(mesh, origin, dir, len, rad) {
  mesh.visible = len > 0.012 && rad > 0.006;
  mesh.position.copy(origin);
  setAlong(mesh, dir);
  mesh.scale.set(Math.max(len, 0.001), Math.max(rad, 0.001), Math.max(rad, 0.001));
}
function contributionAmp(item) {
  const s = document.getElementById('showS').checked ? item.weights.s : 0;
  const px = document.getElementById('showPx').checked ? item.weights.px : 0;
  const py = document.getElementById('showPy').checked ? item.weights.py : 0;
  const pz = document.getElementById('showPz').checked ? item.weights.pz : 0;
  return Math.min(1, (0.34 * s + 0.22 * px + 0.22 * py + 0.22 * pz));
}
function updateHybrids() {
  for (const item of hybridItems) {
    const amp = contributionAmp(item);
    const scale = Math.max(0.08, amp);
    item.f.material.opacity = 0.22 + 0.64 * amp;
    item.b.material.opacity = 0.12 + 0.44 * amp;
    item.h.material.opacity = 0.08 + 0.30 * amp;
    setLobeTransform(item.f, item.origin, item.dir, item.length * scale, item.radius * scale);
    setLobeTransform(item.b, item.origin, item.dir.clone().negate(), item.length * 0.22 * scale, item.radius * 0.28 * scale);
    setLobeTransform(item.h, item.origin, item.dir, item.length * 0.68 * scale, item.radius * 0.45 * scale);
  }
}
function applyCameraForStage(st) {
  const common = {
    projection: 'oblique',
    obliqueAngleDeg: 45,
    depthScale: 0.58,
    distanceScale: 1.0
  };
  if (st === 'atomic') {
    setCameraView({ ...common, target: [-2.28, 0.55, 0], zoom: 1.22 });
  } else if (st === 'individual') {
    setCameraView({ ...common, target: [1.30, 0.55, 0], zoom: 1.16 });
  } else if (st === 'tetra') {
    setCameraView({ ...common, target: [1.94, -1.73, 0], zoom: 1.50 });
  } else {
    setCameraView({ ...common, target: [-0.22, -0.42, 0], heightFraction: 0.84 });
  }
}
function updateVisibility(refit = false) {
  const st = keyForStage(document.getElementById('viewStage').value);
  stages.atomic.visible = st === 'complete' || st === 'atomic';
  stages.individual.visible = st === 'complete' || st === 'individual';
  stages.tetra.visible = st === 'complete' || st === 'tetra';

  for (const k of Object.keys(contribGroups)) {
    const on = document.getElementById(k).checked;
    for (const g of contribGroups[k]) g.visible = on;
  }

  for (const e of labelEntries) {
    const stageOK = st === 'complete' || e.stage === st;
    const contribOK = !e.contrib || document.getElementById(e.contrib).checked;
    e.div.style.visibility = (stageOK && contribOK) ? 'visible' : 'hidden';
  }

  updateHybrids();
  controls.enabled = document.getElementById('orbitScene').checked;
  if (refit) applyCameraForStage(st);
}

const stageSelect = document.getElementById('viewStage');
for (const id of ['showS', 'showPx', 'showPy', 'showPz', 'orbitScene']) {
  document.getElementById(id).addEventListener('change', () => updateVisibility(false));
}
stageSelect.addEventListener('change', () => updateVisibility(true));

const demoSteps = [
  {
    title: 'Full source-style layout',
    narration: 'This view matches the textbook composition: separate atomic orbitals on the left, four individual sp3 hybrids on the right, and the tetrahedral arrangement below.',
    state: { viewStage: 'Complete diagram', showS: true, showPx: true, showPy: true, showPz: true }
  },
  {
    title: 'Start with separate atomic orbitals',
    narration: 'The valence set contains one spherical s orbital and three mutually perpendicular p orbitals. The axes use the printed convention: x right, z up, and y diagonally up-right.',
    state: { viewStage: 'Atomic orbitals', showS: true, showPx: true, showPy: true, showPz: true }
  },
  {
    title: 'Mix them into four sp3 hybrids',
    narration: 'Hybridization combines the s orbital with p_x, p_y, and p_z to produce four orange sp3 hybrids, each drawn with a large lobe and a small opposite lobe.',
    state: { viewStage: 'Individual sp3 hybrids', showS: true, showPx: true, showPy: true, showPz: true }
  },
  {
    title: 'Arrange the hybrids tetrahedrally',
    narration: 'When the four equivalent hybrids share the same origin, their large lobes point in different directions around the central atom.',
    state: { viewStage: 'Tetrahedral arrangement', showS: true, showPx: true, showPy: true, showPz: true }
  }
];
let demoIndex = 0;
function goToStep(i) {
  demoIndex = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[demoIndex];
  stageSelect.value = step.state.viewStage;
  document.getElementById('showS').checked = step.state.showS;
  document.getElementById('showPx').checked = step.state.showPx;
  document.getElementById('showPy').checked = step.state.showPy;
  document.getElementById('showPz').checked = step.state.showPz;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  for (let j = 0; j < demoSteps.length; j++) {
    document.getElementById('step' + j).classList.toggle('active', j === demoIndex);
  }
  updateVisibility(true);
}
for (let i = 0; i < demoSteps.length; i++) {
  document.getElementById('step' + i).addEventListener('click', () => goToStep(i));
}
document.getElementById('nextStep').addEventListener('click', () => goToStep(demoIndex + 1));

updateVisibility(false);
goToStep(0);
